-- Testinnhold for frasekatalogen. Alle hovedkategorier og fraser er merket (T).
-- Slett alt testinnhold senere med:
--   delete from public.phrase_categories where parent_id is null and name like '%(T)';
-- (underkategorier og fraser slettes automatisk med cascade)

do $$
declare c uuid; s uuid; g uuid;
begin
  if exists (select 1 from public.phrase_categories where parent_id is null and name like '%(T)') then
    raise notice 'Testinnhold finnes allerede, hopper over.';
    return;
  end if;









end $$;
